def coin_change(coins, amount):
    if amount == 0:
        return 0
    best = float('inf')
    for c in coins:
        if c <= amount:
            sub = coin_change(coins, amount - c)
            if sub != -1:
                best = min(best, sub + 1)
    return -1 if best == float('inf') else best


def main():
    coins = list(map(int, input().split()))
    amount = int(input())
    print(coin_change(coins, amount))


if __name__ == "__main__":
    main()

def coin_change(coins, amount):
    dp = [float('inf')] * (amount + 1)
    dp[0] = 0
    for a in range(1, amount + 1):
        for c in coins:
            if c <= a and dp[a - c] + 1 < dp[a]:
                dp[a] = dp[a - c] + 1
    return -1 if dp[amount] == float('inf') else dp[amount]


def main():
    coins = list(map(int, input().split()))
    amount = int(input())
    print(coin_change(coins, amount))


if __name__ == "__main__":
    main()

from collections import deque


def coin_change(coins, amount):
    if amount == 0:
        return 0
    visited = [False] * (amount + 1)
    q = deque([(0, 0)])  # (当前金额, 已用硬币数)
    visited[0] = True
    while q:
        cur, step = q.popleft()
        for c in coins:
            nxt = cur + c
            if nxt == amount:
                return step + 1
            if nxt < amount and not visited[nxt]:
                visited[nxt] = True
                q.append((nxt, step + 1))
    return -1


def main():
    coins = list(map(int, input().split()))
    amount = int(input())
    print(coin_change(coins, amount))


if __name__ == "__main__":
    main()
